    fsa->head = (char *)block - (char *)fsa;
}

size_t FSACountFree(const fsa_t *fsa) {
    size_t counter = 0;
    size_t offset = 0;

    assert(fsa);

    offset = fsa->head;

    while (0 != *(size_t *)((const char *)fsa + offset)) {
        offset = *(size_t *)((const char *)fsa + offset);
        ++counter;
    }

    return counter;
}
