```maple
thomasSolver := proc(a, b, c, d) 
  local N, i, w, x;

  N := numelems(d);
  w := Array(1..N);
  x := Array(1..N);

  # Forward Elimination
  w[1] := c[1] / b[1];
  d[1] := d[1] / b[1];
  for i from 2 to N - 1 do
    w[i] := c[i] / (b[i] - a[i] * w[i - 1]);
